/**
 * Editor pane with synced line numbers and textarea.
 */
export class EditorPane {
  private readonly wrapper: HTMLElement;
  private readonly gutter: HTMLElement;
  private readonly textarea: HTMLTextAreaElement;
  private onChange: ((content: string) => void) | null = null;
  private scrollSyncing = false;

  constructor(parent: HTMLElement) {
    this.wrapper = document.createElement('div');
    this.wrapper.className = 'relative flex min-h-0 flex-1 overflow-hidden';

    this.gutter = document.createElement('div');
    this.gutter.className =
      'editor-gutter shrink-0 overflow-hidden border-r border-slate-800 bg-slate-900/50 py-4 pr-3 pl-3 text-right font-mono text-sm leading-6 text-slate-500 select-none';
    this.gutter.setAttribute('aria-hidden', 'true');

    this.textarea = document.createElement('textarea');
    this.textarea.className =
      'editor-textarea min-h-0 flex-1 resize-none border-0 bg-transparent py-4 pr-4 pl-3 font-mono text-sm leading-6 text-slate-100 outline-none caret-sky-400 placeholder:text-slate-600';
    this.textarea.spellcheck = false;
    this.textarea.autocapitalize = 'off';
    this.textarea.autocomplete = 'off';
    this.textarea.setAttribute('aria-label', 'Editor');
    this.textarea.placeholder = 'Start typing…';

    this.textarea.addEventListener('input', () => {
      this.updateLineNumbers();
      this.onChange?.(this.textarea.value);
    });

    this.textarea.addEventListener('scroll', () => this.syncScrollFromTextarea());
    this.gutter.addEventListener('scroll', () => this.syncScrollFromGutter());

    // Tab key inserts spaces instead of changing focus.
    this.textarea.addEventListener('keydown', (e) => {
      if (e.key === 'Tab') {
        e.preventDefault();
        const start = this.textarea.selectionStart;
        const end = this.textarea.selectionEnd;
        const spaces = '  ';
        this.textarea.setRangeText(spaces, start, end, 'end');
        this.updateLineNumbers();
        this.onChange?.(this.textarea.value);
      }
    });

    this.wrapper.append(this.gutter, this.textarea);
    parent.appendChild(this.wrapper);
    this.updateLineNumbers();
  }

  setOnChange(handler: (content: string) => void): void {
    this.onChange = handler;
  }

  setContent(content: string): void {
    this.textarea.value = content;
    this.updateLineNumbers();
  }

  getContent(): string {
    return this.textarea.value;
  }

  focus(): void {
    this.textarea.focus();
  }

  private updateLineNumbers(): void {
    const lines = this.textarea.value.split('\n').length || 1;
    const numbers = Array.from({ length: lines }, (_, i) => i + 1).join('\n');
    this.gutter.textContent = numbers;
  }

  private syncScrollFromTextarea(): void {
    if (this.scrollSyncing) return;
    this.scrollSyncing = true;
    this.gutter.scrollTop = this.textarea.scrollTop;
    this.scrollSyncing = false;
  }

  private syncScrollFromGutter(): void {
    if (this.scrollSyncing) return;
    this.scrollSyncing = true;
    this.textarea.scrollTop = this.gutter.scrollTop;
    this.scrollSyncing = false;
  }
}
