import type { EditorTab, OpenFileResult } from './types';
import { DEFAULT_FILENAME } from './types';
import { EditorPane } from './editor';
import { TabBar } from './tabs';
import {
  openFile,
  registerLaunchHandler,
  saveFile,
  saveFileAs,
} from './filesystem';
import { showToast, showUnsavedDialog } from './dialog';

let tabCounter = 0;

function createTabId(): string {
  tabCounter += 1;
  return `tab-${tabCounter}-${Date.now()}`;
}

function createEmptyTab(filename = DEFAULT_FILENAME): EditorTab {
  return {
    id: createTabId(),
    filename,
    content: '',
    savedContent: '',
  };
}

function isDirty(tab: EditorTab): boolean {
  return tab.content !== tab.savedContent;
}

/**
 * Main application controller — coordinates tabs, editor, and file I/O.
 */
export class TextEditorApp {
  private readonly root: HTMLElement;
  private readonly toolbar: HTMLElement;
  private readonly mainArea: HTMLElement;
  private readonly emptyState: HTMLElement;
  private readonly editorHost: HTMLElement;

  private tabs: EditorTab[] = [];
  private activeTabId: string | null = null;

  private tabBar!: TabBar;
  private editor!: EditorPane;

  constructor(root: HTMLElement) {
    this.root = root;
    this.root.className = 'flex h-[100dvh] flex-col overflow-hidden';

    this.toolbar = this.buildToolbar();
    this.mainArea = document.createElement('main');
    this.mainArea.className = 'flex min-h-0 flex-1 flex-col overflow-hidden';

    this.emptyState = this.buildEmptyState();
    this.editorHost = document.createElement('div');
    this.editorHost.className = 'flex min-h-0 flex-1 flex-col overflow-hidden hidden';

    this.mainArea.append(this.emptyState, this.editorHost);
    this.root.append(this.toolbar, this.mainArea);

    this.tabBar = new TabBar(this.toolbar, {
      onSelect: (id) => this.selectTab(id),
      onClose: (id) => void this.closeTab(id),
    });

    this.editor = new EditorPane(this.editorHost);
    this.editor.setOnChange((content) => this.updateActiveContent(content));

    this.bindKeyboardShortcuts();
    registerLaunchHandler((files) => this.openFilesFromLaunch(files));
    this.render();
  }

  /** Create a new untitled tab. */
  newFile(): void {
    const tab = createEmptyTab(this.nextUntitledName());
    this.tabs.push(tab);
    this.activeTabId = tab.id;
    this.render();
    this.editor.focus();
  }

  /** Open file via picker. */
  async openExistingFile(): Promise<void> {
    try {
      const result = await openFile();
      if (!result) return;
      this.addOpenedFile(result);
    } catch (err) {
      console.error(err);
      showToast('Could not open file.');
    }
  }

  /** Save active tab (Save As if no handle). */
  async saveActiveFile(): Promise<boolean> {
    const tab = this.getActiveTab();
    if (!tab) return false;

    try {
      const result = await saveFile(tab.content, tab.filename, tab.fileHandle);
      if (!result) return false;

      tab.filename = result.filename;
      tab.fileHandle = result.fileHandle;
      tab.savedContent = tab.content;
      this.render();
      showToast(`Saved ${tab.filename}`);
      return true;
    } catch (err) {
      console.error(err);
      showToast('Could not save file.');
      return false;
    }
  }

  /** Always prompt Save As. */
  async saveActiveFileAs(): Promise<boolean> {
    const tab = this.getActiveTab();
    if (!tab) return false;

    try {
      const result = await saveFileAs(tab.content, tab.filename);
      if (!result) return false;

      tab.filename = result.filename;
      tab.fileHandle = result.fileHandle;
      tab.savedContent = tab.content;
      this.render();
      showToast(`Saved ${tab.filename}`);
      return true;
    } catch (err) {
      console.error(err);
      showToast('Could not save file.');
      return false;
    }
  }

  private buildToolbar(): HTMLElement {
    const bar = document.createElement('header');
    bar.className = 'flex shrink-0 flex-col border-b border-slate-800 bg-slate-900 sm:flex-row';

    const actions = document.createElement('div');
    actions.className =
      'flex shrink-0 items-center gap-1 border-b border-slate-800 px-2 py-1 sm:border-b-0 sm:border-r sm:py-0';

    const buttons: Array<{ label: string; action: () => void; title: string }> = [
      { label: 'New', action: () => this.newFile(), title: 'New file (Ctrl+N)' },
      { label: 'Open', action: () => void this.openExistingFile(), title: 'Open file (Ctrl+O)' },
      { label: 'Save', action: () => void this.saveActiveFile(), title: 'Save (Ctrl+S)' },
      {
        label: 'Save As',
        action: () => void this.saveActiveFileAs(),
        title: 'Save as (Ctrl+Shift+S)',
      },
    ];

    for (const { label, action, title } of buttons) {
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className =
        'min-h-touch min-w-touch rounded-lg px-3 text-sm font-medium text-slate-300 hover:bg-slate-800 hover:text-white';
      btn.textContent = label;
      btn.title = title;
      btn.addEventListener('click', action);
      actions.appendChild(btn);
    }

    bar.appendChild(actions);
    return bar;
  }

  private buildEmptyState(): HTMLElement {
    const el = document.createElement('div');
    el.className =
      'flex flex-1 flex-col items-center justify-center gap-6 px-6 text-center';
    el.innerHTML = `
      <div>
        <h1 class="text-2xl font-semibold text-slate-100">Text Editor</h1>
        <p class="mt-2 max-w-sm text-sm text-slate-400">
          Create or open a file to start editing. Works offline once installed.
        </p>
      </div>
      <div class="flex flex-col gap-3 sm:flex-row">
        <button type="button" data-empty="new"
          class="min-h-touch min-w-[10rem] rounded-xl bg-sky-600 px-6 text-sm font-medium text-white hover:bg-sky-500">
          New File
        </button>
        <button type="button" data-empty="open"
          class="min-h-touch min-w-[10rem] rounded-xl border border-slate-700 px-6 text-sm font-medium text-slate-200 hover:bg-slate-800">
          Open File
        </button>
      </div>
    `;

    el.querySelector('[data-empty="new"]')?.addEventListener('click', () => this.newFile());
    el.querySelector('[data-empty="open"]')?.addEventListener('click', () =>
      void this.openExistingFile()
    );

    return el;
  }

  private bindKeyboardShortcuts(): void {
    document.addEventListener('keydown', (e) => {
      const mod = e.ctrlKey || e.metaKey;
      if (!mod) return;

      if (e.key === 'n' || e.key === 'N') {
        e.preventDefault();
        this.newFile();
      } else if (e.key === 'o' || e.key === 'O') {
        e.preventDefault();
        void this.openExistingFile();
      } else if (e.key === 's' || e.key === 'S') {
        e.preventDefault();
        if (e.shiftKey) void this.saveActiveFileAs();
        else void this.saveActiveFile();
      }
    });
  }

  private openFilesFromLaunch(files: OpenFileResult[]): void {
    for (const file of files) {
      this.addOpenedFile(file);
    }
  }

  private addOpenedFile(result: OpenFileResult): void {
    const existing = this.tabs.find(
      (t) => t.fileHandle === result.fileHandle && result.fileHandle != null
    );
    if (existing) {
      this.activeTabId = existing.id;
      this.render();
      return;
    }

    const tab: EditorTab = {
      id: createTabId(),
      filename: result.filename,
      content: result.content,
      savedContent: result.content,
      fileHandle: result.fileHandle,
    };
    this.tabs.push(tab);
    this.activeTabId = tab.id;
    this.render();
    this.editor.focus();
  }

  private nextUntitledName(): string {
    const untitled = this.tabs.filter((t) => t.filename.startsWith('untitled'));
    if (untitled.length === 0) return 'untitled.txt';
    return `untitled-${untitled.length + 1}.txt`;
  }

  private getActiveTab(): EditorTab | undefined {
    return this.tabs.find((t) => t.id === this.activeTabId);
  }

  private selectTab(id: string): void {
    // Persist current buffer before switching.
    this.flushActiveEditor();
    this.activeTabId = id;
    this.render();
    this.editor.focus();
  }

  private async closeTab(id: string): Promise<void> {
    const tab = this.tabs.find((t) => t.id === id);
    if (!tab) return;

    if (id === this.activeTabId) this.flushActiveEditor();

    if (isDirty(tab)) {
      const choice = await showUnsavedDialog(tab.filename);
      if (choice === 'cancel') return;

      if (choice === 'save') {
        // Temporarily make this tab active so save uses its content.
        const prevActive = this.activeTabId;
        this.activeTabId = id;
        const saved = await this.saveActiveFile();
        this.activeTabId = prevActive;
        if (!saved) return;
      }
    }

    this.tabs = this.tabs.filter((t) => t.id !== id);

    if (this.activeTabId === id) {
      this.activeTabId = this.tabs.length ? this.tabs[this.tabs.length - 1].id : null;
    }

    this.render();
    if (this.activeTabId) this.editor.focus();
  }

  private flushActiveEditor(): void {
    const tab = this.getActiveTab();
    if (!tab) return;
    tab.content = this.editor.getContent();
  }

  private updateActiveContent(content: string): void {
    const tab = this.getActiveTab();
    if (!tab) return;
    tab.content = content;
    this.tabBar.setTabs(this.tabs, this.activeTabId);
  }

  private render(): void {
    const hasTabs = this.tabs.length > 0;
    this.emptyState.classList.toggle('hidden', hasTabs);
    this.editorHost.classList.toggle('hidden', !hasTabs);

    this.tabBar.setTabs(this.tabs, this.activeTabId);

    const active = this.getActiveTab();
    if (active) {
      this.editor.setContent(active.content);
    }
  }
}
